//!
//! Integration-test binaries in this workspace masquerade as the real `codex`
//! CLI so that child re-execs (e.g. `apply_patch`, `codex-linux-sandbox`) can
//! be dispatched via the "arg0 trick". Historically each test crate open-coded
//! the same `#[ctor]` that inspects `argv0`/`argv1`, points `CODEX_HOME` at a
//! throwaway directory, installs the arg0 aliases, and then restores the
//! previous `CODEX_HOME`. This crate centralizes that logic behind
//! [`configure_test_binary_dispatch`].

use std::ffi::OsString;
use std::path::Path;

use codex_arg0::Arg0DispatchPaths;
use codex_arg0::Arg0PathEntryGuard;
use codex_arg0::arg0_dispatch;

const CODEX_HOME_ENV_VAR: &str = "CODEX_HOME";

/// What [`configure_test_binary_dispatch`] should do for the current process
/// invocation, as decided by the caller-supplied `classify` closure.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TestBinaryDispatchMode {
    /// Dispatch via arg0 (running any sub-command the binary was invoked as)
    /// and return `None`. No test-owned `CODEX_HOME` is installed.
    DispatchArg0Only,
    /// Do nothing and return `None`.
    Skip,
    /// Set up a temporary `CODEX_HOME`, install the arg0 dispatch aliases,
    /// restore the previous `CODEX_HOME`, and return the resulting guard.
    InstallAliases,
}

/// Keeps the temporary `CODEX_HOME` directory and the arg0 path entry guard
/// alive for the lifetime of the test process.
pub struct TestBinaryDispatchGuard {
    // Retained so the temporary CODEX_HOME (and the arg0 aliases installed
    // beneath it) survive for the duration of the test process.
    _codex_home: tempfile::TempDir,
    arg0: Arg0PathEntryGuard,
    // Retained purely so the previous CODEX_HOME value is observable while
    // debugging; the environment is restored eagerly during setup.
    _previous_codex_home: Option<OsString>,
}

impl TestBinaryDispatchGuard {
    /// Paths to the helper executables discovered while installing the arg0
    /// aliases (e.g. `codex-linux-sandbox`).
    pub fn paths(&self) -> &Arg0DispatchPaths {
        self.arg0.paths()
    }
}

/// Reads `argv0`/`argv1`, calls `classify(exe_name, argv1)` to determine the
/// dispatch mode, and acts accordingly.
///
/// This is intended to be called from a `#[ctor]` static initializer in test
/// binaries, before any test threads are spawned. Because it mutates the
/// `CODEX_HOME` environment variable while installing the aliases, it must not
/// run concurrently with other threads.
pub fn configure_test_binary_dispatch<F>(
    codex_home_prefix: &str,
    classify: F,
) -> Option<TestBinaryDispatchGuard>
where
    F: FnOnce(&str, Option<&str>) -> TestBinaryDispatchMode,
{
    let mut args = std::env::args_os();
    let argv0 = args.next().unwrap_or_default();
    let exe_name = Path::new(&argv0)
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("");
    let argv1_os = args.next();
    let argv1 = argv1_os.as_ref().and_then(|value| value.to_str());

    match classify(exe_name, argv1) {
        TestBinaryDispatchMode::DispatchArg0Only => {
            // Run whatever sub-command this invocation maps to. If it does not
            // dispatch away, drop the returned guard so no aliases leak.
            let _ = arg0_dispatch();
            None
        }
        TestBinaryDispatchMode::Skip => None,
        TestBinaryDispatchMode::InstallAliases => {
            let codex_home = tempfile::Builder::new()
                .prefix(codex_home_prefix)
                .tempdir()
                .ok()?;

            let previous_codex_home = std::env::var_os(CODEX_HOME_ENV_VAR);
            // arg0_dispatch() installs helper links under CODEX_HOME/tmp. Point
            // it at a test-owned temp dir so startup never mutates the
            // developer's real ~/.codex.
            //
            // Safety: this is intended to run from a #[ctor], before any test
            // threads exist.
            unsafe {
                std::env::set_var(CODEX_HOME_ENV_VAR, codex_home.path());
            }

            let arg0 = arg0_dispatch();

            // Restore the process environment immediately so later tests
            // observe the same CODEX_HOME state they started with.
            match previous_codex_home.as_ref() {
                Some(value) => unsafe {
                    std::env::set_var(CODEX_HOME_ENV_VAR, value);
                },
                None => unsafe {
                    std::env::remove_var(CODEX_HOME_ENV_VAR);
                },
            }

            Some(TestBinaryDispatchGuard {
                _codex_home: codex_home,
                arg0: arg0?,
                _previous_codex_home: previous_codex_home,
            })
        }
    }
}
